		registry: {
			"title": "Alert",
			"description": "Displays a callout for user attention.",
			"dependencies": ["class-variance-authority"],
			"files": [
				{
					"path": "src/components/ui/alert/alert.marko",
					"content": "import { alertVariants, type AlertVariants } from \"./variants.ts\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\">, AlertVariants {}\n\n<const/{ variant, class: className, content, ...rest }=input/>\n\n<div ...rest role=\"alert\" data-slot=\"alert\" class=cn(alertVariants({ variant }), className)>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/alert/description.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  data-slot=\"alert-description\"\n  class=cn(\n    \"text-muted-foreground col-start-2 grid justify-items-start gap-1 text-sm [&_p]:leading-relaxed\",\n    className,\n  )\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/alert/title.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  data-slot=\"alert-title\"\n  class=cn(\"col-start-2 line-clamp-1 min-h-4 font-medium tracking-tight\", className)\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/alert/variants.ts",
					"content": "import { cva, type VariantProps } from \"class-variance-authority\";\n\nexport const alertVariants = cva(\n  \"relative w-full rounded-lg border px-4 py-3 text-sm grid has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] grid-cols-[0_1fr] has-[>svg]:gap-x-3 gap-y-0.5 items-start [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-card text-card-foreground\",\n        destructive:\n          \"text-destructive bg-card [&>svg]:text-current *:data-[slot=alert-description]:text-destructive/90\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n    },\n  },\n);\n\nexport type AlertVariants = VariantProps<typeof alertVariants>;\n"
				}
			]
		},
