	"alert-dialog": {
		docs: {
			description: "A modal dialog that interrupts the user with important content and expects a response.",
			usageTags: `<AlertDialog>`,
			importSnippet: `import AlertDialog from "@/components/ui/alert-dialog/alert-dialog.marko";`,
			usageSnippet: `<AlertDialog>
  <@trigger|props|>
    <Button ...props variant="outline">Show Dialog</Button>
  </@trigger>
  <@title>Are you absolutely sure?</@title>
  <@description>
    This action cannot be undone.
  </@description>
</AlertDialog>`,
			examples: [
				{
					name: "alert-dialog-demo",
					title: "Basic",
					description: "A dialog with a title, description, and cancel and continue buttons."
				},
				{
					name: "alert-dialog-destructive",
					title: "Destructive",
					description: "Override `cancelText` and `actionText`, and run side effects on confirm with the `action` callback."
				},
				{
					name: "alert-dialog-controlled",
					title: "Controlled",
					description: "Zag machines are controlled: an `open` prop without a change handler never moves. Pair it with `openChange`, or use Marko's bind shorthand `open:=state`."
				}
			]
		},
		registry: {
			"title": "Alert Dialog",
			"description": "A modal dialog that interrupts the user with important content and expects a response.",
			"dependencies": ["@zag-js/dialog", "marko-ui"],
			"files": [{
				"path": "src/components/ui/alert-dialog/alert-dialog.marko",
				"content": "// Guide: /docs/creating-components · adapter internals: /docs/zag-adapter\n// Authoring rules: notes/component-authoring.md (v2 pattern)\nimport * as dialogMachine from \"@zag-js/dialog\";\nimport type { MachineInput } from \"marko-ui\";\nimport { buttonVariants } from \"../button/variants.ts\";\nimport { cn } from \"../../../lib/utils.ts\";\n\n// MachineInput = native <div> attributes ∩ the machine's full Props, with\n// `id` made optional (generated below, overridable). `openChange` is\n// additive sugar enabling Marko's two-way bind shorthand\n// (<AlertDialog open:=myState/>); Zag's own `onOpenChange` also works and\n// receives the details object.\nexport type Input = MachineInput<\"div\", dialogMachine.Props> & {\n  openChange?: (open: boolean) => void;\n  trigger?: Marko.Body<[Record<string, unknown>]>;\n  title?: Marko.Body;\n  description?: Marko.Body;\n  cancelText?: string;\n  actionText?: string;\n  action?: () => void;\n};\n\n// The three-tag wiring (see /docs/creating-components):\n// 1. <machine-props> picks the machine's props out of `input` by name and\n//    merges the attributes written on it — callback adaptations live HERE,\n//    visibly, because they are this component's public contract.\n// 2. <service> creates and owns the running machine (client-only; SSR\n//    renders from a throwaway never-started instance).\n// 3. <connect> returns `api` as a GETTER — call it at every use site.\n//    Getters are the serializable currency of Marko's resumability: the\n//    api object itself must never become reactive state.\n<machine-props/machineProps from=input pick=dialogMachine.props\n  role=\"alertdialog\"\n  closeOnInteractOutside=false\n  closeOnEscape=false\n  onOpenChange(details: dialogMachine.OpenChangeDetails) {\n    input.onOpenChange?.(details);\n    input.openChange?.(details.open);\n  }/>\n<service/service machine=() => dialogMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  dialogMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n// Whatever is neither machine-owned (splitProps) nor component-owned\n// (class, openChange, trigger, title, description, cancelText, actionText,\n// action) passes through to the content element: aria-*, data-*...\n<const/nativeAttrs=() => {\n  const {\n    class: ownClass,\n    openChange: ownChangeHandler,\n    trigger: ownTrigger,\n    title: ownTitle,\n    description: ownDescription,\n    cancelText: ownCancelText,\n    actionText: ownActionText,\n    action: ownAction,\n    ...native\n  } = dialogMachine.splitProps(input)[1];\n  return native;\n}>\n\n<if=input.trigger>\n  <${input.trigger}({ ...api().getTriggerProps(), \"data-slot\": \"alert-dialog-trigger\" })/>\n</if>\n<portal>\n  <if=api().open>\n    <div\n      ...api().getBackdropProps()\n      data-slot=\"alert-dialog-overlay\"\n      class=\"fixed inset-0 z-50 bg-black/50 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=closed]:animate-out data-[state=closed]:fade-out-0\"\n    />\n    <div ...api().getPositionerProps() data-slot=\"alert-dialog-positioner\" class=\"fixed inset-0 z-50 flex items-center justify-center p-4\">\n      <div\n        ...nativeAttrs()\n        ...api().getContentProps()\n        data-slot=\"alert-dialog-content\"\n        class=cn(\n          \"bg-background data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 grid w-full max-w-[calc(100%-2rem)] gap-4 rounded-lg border p-6 shadow-lg duration-200 sm:max-w-lg\",\n          input.class,\n        )\n      >\n        <div data-slot=\"alert-dialog-header\" class=\"flex flex-col gap-2 text-center sm:text-left\">\n          <h2 ...api().getTitleProps() data-slot=\"alert-dialog-title\" class=\"text-lg font-semibold\">\n            <${input.title}/>\n          </h2>\n          <p ...api().getDescriptionProps() data-slot=\"alert-dialog-description\" class=\"text-muted-foreground text-sm\">\n            <${input.description}/>\n          </p>\n        </div>\n        <div data-slot=\"alert-dialog-footer\" class=\"flex flex-col-reverse gap-2 sm:flex-row sm:justify-end\">\n          <button ...api().getCloseTriggerProps() data-slot=\"alert-dialog-cancel\" class=buttonVariants({ variant: \"outline\" })>\n            ${input.cancelText ?? \"Cancel\"}\n          </button>\n          <button\n            ...api().getCloseTriggerProps()\n            data-slot=\"alert-dialog-action\"\n            class=buttonVariants({ variant: \"default\" })\n            onClick(event: Event, element?: Element) {\n              input.action?.();\n              api().getCloseTriggerProps().onClick?.(event, element);\n            }\n          >\n            ${input.actionText ?? \"Continue\"}\n          </button>\n        </div>\n      </div>\n    </div>\n  </if>\n</portal>\n\n// Parents can receive the api getter: <AlertDialog/alertDialogApi/> then\n// `alertDialogApi().open` — it stays live across machine updates.\n<return=api>"
			}]
		},
		demos: {
			"alert-dialog-controlled": {
				demoId: "alert-dialog/alert-dialog-controlled",
				source: "<let/open=false/>\n\n<div class=\"flex items-center gap-4\">\n  <AlertDialog open=open openChange=(o) => { open = o; }>\n    <@trigger|props|>\n      <Button ...props variant=\"outline\">${open ? \"Close\" : \"Open\"}</Button>\n    </@trigger>\n    <@title>Controlled alert dialog</@title>\n    <@description>The open state is controlled by the parent component.</@description>\n  </AlertDialog>\n  <span class=\"text-sm text-muted-foreground\">open: ${String(open)}</span>\n</div>"
			},
			"alert-dialog-demo": {
				demoId: "alert-dialog/alert-dialog-demo",
				source: "<AlertDialog>\n  <@trigger|props|>\n    <Button ...props variant=\"outline\">Show Dialog</Button>\n  </@trigger>\n  <@title>Are you absolutely sure?</@title>\n  <@description>\n    This action cannot be undone. This will permanently delete your account and remove your data from our servers.\n  </@description>\n</AlertDialog>"
			},
			"alert-dialog-destructive": {
				demoId: "alert-dialog/alert-dialog-destructive",
				source: "<AlertDialog\n  cancelText=\"No, keep it\"\n  actionText=\"Yes, delete it\"\n  action=() => { console.log(\"deleted\"); }\n>\n  <@trigger|props|>\n    <Button ...props variant=\"destructive\">Delete account</Button>\n  </@trigger>\n  <@title>Delete account</@title>\n  <@description>\n    This will permanently delete your account. This action is irreversible.\n  </@description>\n</AlertDialog>"
			}
		}
	},
