		registry: {
			"title": "Button Group",
			"description": "A container that groups related buttons together, merging their borders and corners.",
			"dependencies": ["class-variance-authority"],
			"files": [
				{
					"path": "src/components/ui/button-group/button-group.marko",
					"content": "import { buttonGroupVariants, type ButtonGroupVariants } from \"./variants.ts\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\">, ButtonGroupVariants {}\n\n<const/{ orientation, class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  role=\"group\"\n  data-slot=\"button-group\"\n  data-orientation=(orientation ?? \"horizontal\")\n  class=cn(buttonGroupVariants({ orientation }), className)\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/button-group/separator.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {\n  orientation?: \"horizontal\" | \"vertical\";\n}\n\n<const/{ orientation = \"vertical\", class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  data-slot=\"button-group-separator\"\n  role=\"separator\"\n  data-orientation=orientation\n  class=cn(\n    \"bg-input relative !m-0 self-stretch data-[orientation=vertical]:h-auto data-[orientation=vertical]:w-px data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full\",\n    className,\n  )\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/button-group/text.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  data-slot=\"button-group-text\"\n  class=cn(\n    \"bg-muted flex items-center gap-2 rounded-md border px-4 text-sm font-medium shadow-xs [&_svg]:pointer-events-none [&_svg]:size-4\",\n    className,\n  )\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/button-group/variants.ts",
					"content": "import { cva, type VariantProps } from \"class-variance-authority\";\n\nexport const buttonGroupVariants = cva(\n  \"flex w-fit items-stretch [&>*]:focus-visible:relative [&>*]:focus-visible:z-10 [&>[data-slot=select-trigger]:not([class*='w-'])]:w-fit [&>input]:flex-1 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-r-md has-[>[data-slot=button-group]]:gap-2\",\n  {\n    variants: {\n      orientation: {\n        horizontal:\n          \"[&>*:not(:first-child)]:rounded-l-none [&>*:not(:first-child)]:border-l-0 [&>*:not(:last-child)]:rounded-r-none\",\n        vertical:\n          \"flex-col [&>*:not(:first-child)]:rounded-t-none [&>*:not(:first-child)]:border-t-0 [&>*:not(:last-child)]:rounded-b-none\",\n      },\n    },\n    defaultVariants: {\n      orientation: \"horizontal\",\n    },\n  },\n);\n\nexport type ButtonGroupVariants = VariantProps<typeof buttonGroupVariants>;\n"
				}
			]
		},
