		registry: {
			"title": "Input Group",
			"description": "Groups inputs and addons together, with a wide range of customization options.",
			"dependencies": ["class-variance-authority"],
			"files": [
				{
					"path": "src/components/ui/input-group/addon.marko",
					"content": "import { inputGroupAddonVariants, type InputGroupAddonVariants } from \"./variants.ts\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\">, InputGroupAddonVariants {}\n\n<const/{ align, class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  role=\"group\"\n  data-slot=\"input-group-addon\"\n  data-align=align ?? \"inline-start\"\n  onClick(event) {\n    if ((event.target as HTMLElement).closest(\"button\")) return;\n    const control = (event.currentTarget as HTMLElement)\n      .closest(\"[data-slot=input-group]\")\n      ?.querySelector<HTMLElement>(\"[data-slot=input-group-control]\");\n    control?.focus();\n  }\n  class=cn(inputGroupAddonVariants({ align }), className)\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/input-group/button.marko",
					"content": "import Button from \"../button/button.marko\";\nimport type { ButtonVariants } from \"../button/variants.ts\";\nimport { inputGroupButtonVariants, type InputGroupButtonVariants } from \"./variants.ts\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input\n  extends Omit<Marko.Input<\"button\">, \"size\">,\n    Pick<ButtonVariants, \"variant\">,\n    InputGroupButtonVariants {}\n\n<const/{ variant, size, class: className, content, ...rest }=input/>\n\n<Button\n  ...rest\n  type=input.type ?? \"button\"\n  data-slot=\"input-group-button\"\n  variant=variant ?? \"ghost\"\n  size=\"sm\"\n  class=cn(inputGroupButtonVariants({ size: size ?? \"xs\" }), className)\n>\n  <${content}/>\n</Button>\n"
				},
				{
					"path": "src/components/ui/input-group/input-group.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<div\n  ...rest\n  role=\"group\"\n  data-slot=\"input-group\"\n  class=cn(\n    \"group/input-group border-input dark:bg-input/30 relative flex w-full items-center rounded-md border shadow-xs transition-[color,box-shadow] outline-none\",\n    \"h-9 has-[>textarea]:h-auto\",\n    \"focus-within:border-ring focus-within:ring-ring/50 focus-within:ring-[3px]\",\n    \"has-[[data-slot=input-group-control]:disabled]:pointer-events-none has-[[data-slot=input-group-control]:disabled]:opacity-50\",\n    \"has-[[aria-invalid=true]]:ring-destructive/20 dark:has-[[aria-invalid=true]]:ring-destructive/40 has-[[aria-invalid=true]]:border-destructive\",\n    \"[&>input]:flex-1\",\n    className,\n  )\n>\n  <${content}/>\n</div>\n"
				},
				{
					"path": "src/components/ui/input-group/input.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"input\"> {}\n\n<const/{ type, class: className, ...rest }=input/>\n\n<input\n  ...rest\n  type=type\n  data-slot=\"input-group-control\"\n  class=cn(\n    \"flex-1 rounded-none border-0 bg-transparent shadow-none focus-visible:ring-0 dark:bg-transparent\",\n    \"h-full px-3 py-1 text-base outline-none file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm\",\n    className,\n  )\n/>\n"
				},
				{
					"path": "src/components/ui/input-group/text.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"span\"> {}\n\n<const/{ class: className, content, ...rest }=input/>\n\n<span\n  ...rest\n  data-slot=\"input-group-text\"\n  class=cn(\n    \"text-muted-foreground flex items-center gap-2 text-sm [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none\",\n    className,\n  )\n>\n  <${content}/>\n</span>\n"
				},
				{
					"path": "src/components/ui/input-group/textarea.marko",
					"content": "import { cn } from \"../../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"textarea\"> {}\n\n<const/{ class: className, ...rest }=input/>\n\n<textarea\n  ...rest\n  data-slot=\"input-group-control\"\n  class=cn(\n    \"flex-1 resize-none rounded-none border-0 bg-transparent py-3 shadow-none focus-visible:ring-0 dark:bg-transparent\",\n    \"field-sizing-content min-h-16 w-full px-3 text-base outline-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm\",\n    className,\n  )\n/>\n"
				},
				{
					"path": "src/components/ui/input-group/variants.ts",
					"content": "import { cva, type VariantProps } from \"class-variance-authority\";\n\nexport const inputGroupAddonVariants = cva(\n  \"text-muted-foreground flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-sm font-medium select-none [&>svg:not([class*='size-'])]:size-4 [&>kbd]:rounded-[calc(var(--radius)-5px)] group-data-[disabled=true]/input-group:opacity-50\",\n  {\n    variants: {\n      align: {\n        \"inline-start\":\n          \"order-first pl-3 has-[>button]:ml-[-0.45rem] has-[>kbd]:ml-[-0.35rem]\",\n        \"inline-end\":\n          \"order-last pr-3 has-[>button]:mr-[-0.45rem] has-[>kbd]:mr-[-0.35rem]\",\n        \"block-start\":\n          \"order-first w-full justify-start px-3 pt-3 [.border-b]:pb-3 group-has-[>input]/input-group:pt-2.5\",\n        \"block-end\":\n          \"order-last w-full justify-start px-3 pb-3 [.border-t]:pt-3 group-has-[>input]/input-group:pb-2.5\",\n      },\n    },\n    defaultVariants: {\n      align: \"inline-start\",\n    },\n  },\n);\n\nexport type InputGroupAddonVariants = VariantProps<typeof inputGroupAddonVariants>;\n\nexport const inputGroupButtonVariants = cva(\n  \"text-sm shadow-none flex gap-2 items-center\",\n  {\n    variants: {\n      size: {\n        xs: \"h-6 gap-1 px-2 rounded-[calc(var(--radius)-5px)] [&>svg:not([class*='size-'])]:size-3.5 has-[>svg]:px-2\",\n        sm: \"h-8 px-2.5 gap-1.5 rounded-md has-[>svg]:px-2.5\",\n        \"icon-xs\": \"size-6 rounded-[calc(var(--radius)-5px)] p-0 has-[>svg]:p-0\",\n        \"icon-sm\": \"size-8 p-0 has-[>svg]:p-0\",\n      },\n    },\n    defaultVariants: {\n      size: \"xs\",\n    },\n  },\n);\n\nexport type InputGroupButtonVariants = VariantProps<typeof inputGroupButtonVariants>;\n"
				}
			]
		},
