	"popover": {
		docs: {
			description: "Displays rich content in a portal, triggered by a button.",
			usageTags: `<Popover>`,
			importSnippet: `import Popover from "@/components/ui/popover/popover.marko";`,
			usageSnippet: `<Popover>
  <@trigger|props|>
    <button ...props>Open</button>
  </@trigger>
  <@content>
    <p>Place any content here.</p>
  </@content>
</Popover>`,
			examples: [
				{
					name: "popover-demo",
					title: "Default",
					description: "A popover with a header and description, anchored to its trigger."
				},
				{
					name: "popover-placement",
					title: "Placement",
					description: "Pass `positioning` through to the underlying Zag machine to control placement."
				},
				{
					name: "popover-controlled",
					title: "Controlled",
					description: "Zag machines are controlled: an `open` prop without a change handler never moves. Pair it with `openChange`, or use Marko's bind shorthand `open:=state`."
				}
			]
		},
		registry: {
			"title": "Popover",
			"description": "Displays rich content in a portal, triggered by a button.",
			"dependencies": ["@zag-js/popover", "marko-ui"],
			"files": [{
				"path": "src/components/ui/popover/popover.marko",
				"content": "import * as popoverMachine from \"@zag-js/popover\";\nimport type { MachineInput } from \"marko-ui\";\nimport { positionerStyle } from \"marko-ui\";\nimport { cn } from \"../../../lib/utils.ts\";\n\n// MachineInput = native <div> attributes ∩ the machine's full Props, with\n// `id` made optional (generated below, overridable). `openChange` is\n// additive sugar enabling Marko's two-way bind shorthand\n// (<Popover open:=myState/>); Zag's own `onOpenChange` also works and\n// receives the details object.\nexport type Input = MachineInput<\"div\", popoverMachine.Props> & {\n  /** Trigger render-prop — the element that opens the popover. */\n  trigger: Marko.Body<[Record<string, unknown>]>;\n  /** Popover content shown when open. */\n  content: Marko.Body;\n  openChange?: (open: boolean) => void;\n};\n\n<machine-props/machineProps from=input pick=popoverMachine.props\n  onOpenChange(details: popoverMachine.OpenChangeDetails) {\n    input.onOpenChange?.(details);\n    input.openChange?.(details.open);\n  }/>\n<service/service machine=() => popoverMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  popoverMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n<${input.trigger}({ ...api().getTriggerProps(), \"data-slot\": \"popover-trigger\" })/>\n<portal>\n  <if=api().open>\n    <div ...api().getPositionerProps() style=positionerStyle data-slot=\"popover-positioner\">\n      <div\n        ...api().getContentProps()\n        data-slot=\"popover-content\"\n        class=cn(\n          \"bg-popover text-popover-foreground z-50 w-72 rounded-md border p-4 shadow-md outline-hidden\",\n          \"data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95\",\n          \"data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2\",\n          input.class,\n        )\n      >\n        <${input.content}/>\n      </div>\n    </div>\n  </if>\n</portal>\n\n<return=api>\n"
			}]
		},
		demos: {
			"popover-controlled": {
				demoId: "popover/popover-controlled",
				source: "<let/open=false/>\n\n<div class=\"flex items-center gap-4\">\n  <Popover\n    open=open\n    openChange=(next) => { open = next; }\n  >\n    <@trigger|props|>\n      <Button ...props variant=\"outline\">${open ? \"Close\" : \"Open\"}</Button>\n    </@trigger>\n    <@content>\n      <p class=\"text-sm\">Controlled popover content.</p>\n    </@content>\n  </Popover>\n  <span class=\"text-sm text-muted-foreground\">open: ${String(open)}</span>\n</div>"
			},
			"popover-demo": {
				demoId: "popover/popover-demo",
				source: "<Popover>\n  <@trigger|props|>\n    <Button ...props variant=\"outline\">Open popover</Button>\n  </@trigger>\n  <@content>\n    <div class=\"grid gap-2\">\n      <h4 class=\"leading-none font-medium\">Dimensions</h4>\n      <p class=\"text-muted-foreground text-sm\">\n        Set the dimensions for the layer.\n      </p>\n    </div>\n  </@content>\n</Popover>"
			},
			"popover-placement": {
				demoId: "popover/popover-placement",
				source: "<Popover positioning={ placement: \"right-start\" }>\n  <@trigger|props|>\n    <Button ...props variant=\"outline\">Right start</Button>\n  </@trigger>\n  <@content>\n    <p class=\"text-sm\">Positioned to the right of the trigger.</p>\n  </@content>\n</Popover>"
			}
		}
	},
