	"switch": {
		docs: {
			description: "A control that allows the user to toggle between checked and not checked.",
			usageTags: `<Switch>`,
			importSnippet: `import Switch from "@/components/ui/switch/switch.marko";`,
			usageSnippet: `<Switch checked:=airplaneMode/>`,
			examples: [
				{
					name: "switch-demo",
					title: "Basic",
					description: "A switch paired with a label via the shared id."
				},
				{
					name: "switch-checked",
					title: "Checked",
					description: "Pass `checked` for a controlled switch, or `defaultChecked` to set only the initial state."
				},
				{
					name: "switch-disabled",
					title: "Disabled",
					description: "A disabled switch is skipped by the tab order and ignores pointer input."
				},
				{
					name: "switch-controlled",
					title: "Controlled",
					description: "Zag machines are controlled: a `checked` prop without a change handler never moves. Pair it with `checkedChange`, or use Marko's bind shorthand `checked:=state`."
				}
			]
		},
		registry: {
			"title": "Switch",
			"description": "A control that allows the user to toggle between checked and not checked.",
			"dependencies": ["@zag-js/switch", "marko-ui"],
			"files": [{
				"path": "src/components/ui/switch/switch.marko",
				"content": "// Reference implementation of a marko-ui component.\n// Guide: /docs/creating-components · adapter internals: /docs/zag-adapter\n// Authoring rules: notes/component-authoring.md (v2 pattern)\nimport * as switchMachine from \"@zag-js/switch\";\nimport type { MachineInput } from \"marko-ui\";\nimport { cn } from \"../../../lib/utils.ts\";\n\n// MachineInput = native <input> attributes ∩ the machine's full Props, with\n// `id` made optional (generated below, overridable). `checkedChange` is\n// additive sugar enabling Marko's two-way bind shorthand\n// (<Switch checked:=myState/>); Zag's own `onCheckedChange` also works and\n// receives the details object.\nexport type Input = MachineInput<\"input\", switchMachine.Props> & {\n  checkedChange?: (checked: boolean) => void;\n};\n\n// The three-tag wiring (see /docs/creating-components):\n// 1. <machine-props> picks the machine's props out of `input` by name and\n//    merges the attributes written on it — callback adaptations live HERE,\n//    visibly, because they are this component's public contract.\n// 2. <service> creates and owns the running machine (client-only; SSR\n//    renders from a throwaway never-started instance).\n// 3. <connect> returns `api` as a GETTER — call it at every use site.\n//    Getters are the serializable currency of Marko's resumability: the\n//    api object itself must never become reactive state.\n<machine-props/machineProps from=input pick=switchMachine.props\n  onCheckedChange(details: switchMachine.CheckedChangeDetails) {\n    input.onCheckedChange?.(details);\n    input.checkedChange?.(details.checked);\n  }/>\n<service/service machine=() => switchMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  switchMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n// Whatever is neither machine-owned (splitProps) nor component-owned\n// (class, checkedChange) passes through to the hidden input: aria-*,\n// data-*, form attributes...\n<const/nativeAttrs=() => {\n  const {\n    class: ownClass,\n    checkedChange: ownChangeHandler,\n    ...native\n  } = switchMachine.splitProps(input)[1];\n  return native;\n}>\n\n<label\n  ...api().getRootProps()\n  data-slot=\"switch-label\"\n  class=\"inline-flex items-center gap-2\"\n>\n  <span\n    ...api().getControlProps()\n    data-slot=\"switch\"\n    class=cn(\n      \"peer inline-flex h-[1.15rem] w-8 shrink-0 items-center rounded-full border border-transparent shadow-xs transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=unchecked]:bg-input dark:data-[state=unchecked]:bg-input/80\",\n      input.class,\n    )\n  >\n    <span\n      ...api().getThumbProps()\n      data-slot=\"switch-thumb\"\n      class=\"pointer-events-none block size-4 rounded-full bg-background ring-0 transition-transform data-[state=unchecked]:translate-x-0 data-[state=checked]:translate-x-[calc(100%-2px)] dark:data-[state=unchecked]:bg-foreground dark:data-[state=checked]:bg-primary-foreground\"\n    />\n  </span>\n  <input ...nativeAttrs() ...api().getHiddenInputProps()>\n</label>\n\n// Parents can receive the api getter: <Switch/switchApi/> then\n// `switchApi().checked` — it stays live across machine updates.\n<return=api>\n"
			}]
		},
		demos: {
			"switch-checked": {
				demoId: "switch/switch-checked",
				source: "<Switch checked aria-label=\"Notifications\"/>"
			},
			"switch-controlled": {
				demoId: "switch/switch-controlled",
				source: "<let/checked=true/>\n\n<div class=\"flex items-center gap-4\">\n  <Switch\n    aria-label=\"Notifications\"\n    checked=checked\n    checkedChange=(next) => { checked = next; }\n  />\n  <span class=\"text-sm text-muted-foreground\">checked: ${String(checked)}</span>\n</div>"
			},
			"switch-demo": {
				demoId: "switch/switch-demo",
				source: "<Switch id=\"airplane-mode\">Airplane Mode</Switch>"
			},
			"switch-disabled": {
				demoId: "switch/switch-disabled",
				source: "<div class=\"flex items-center gap-4\">\n  <Switch disabled aria-label=\"Disabled switch\"/>\n  <Switch checked disabled aria-label=\"Disabled checked switch\"/>\n</div>"
			}
		}
	},
