		registry: {
			"title": "Tags Input",
			"description": "An input for entering a list of tags, with keyboard navigation, inline editing, and paste splitting.",
			"dependencies": ["@zag-js/tags-input", "marko-ui"],
			"files": [{
				"path": "src/components/ui/tags-input/tags-input.marko",
				"content": "import * as tagsInputMachine from \"@zag-js/tags-input\";\nimport type { MachineInput } from \"marko-ui\";\nimport { cn } from \"../../../lib/utils.ts\";\n\nexport type Input = MachineInput<\"div\", tagsInputMachine.Props> & {\n  valueChange?: (value: string[]) => void;\n  inputValueChange?: (inputValue: string) => void;\n  highlightedValueChange?: (highlightedValue: string | null) => void;\n  label?: string;\n};\n\n<machine-props/machineProps from=input pick=tagsInputMachine.props\n  onValueChange(details: tagsInputMachine.ValueChangeDetails) {\n    input.onValueChange?.(details);\n    input.valueChange?.(details.value);\n  }\n  onInputValueChange(details: tagsInputMachine.InputValueChangeDetails) {\n    input.onInputValueChange?.(details);\n    input.inputValueChange?.(details.inputValue);\n  }\n  onHighlightChange(details: tagsInputMachine.HighlightChangeDetails) {\n    input.onHighlightChange?.(details);\n    input.highlightedValueChange?.(details.highlightedValue);\n  }/>\n<service/service machine=() => tagsInputMachine.machine props=machineProps/>\n<connect/api=(service, normalizeProps) =>\n  tagsInputMachine.connect(service, normalizeProps)\n  service=service\n/>\n\n<const/nativeAttrs=() => {\n  const {\n    class: ownClass,\n    valueChange: ownValueChangeHandler,\n    inputValueChange: ownInputValueChangeHandler,\n    highlightedValueChange: ownHighlightedValueChangeHandler,\n    label: ownLabel,\n    ...native\n  } = tagsInputMachine.splitProps(input)[1];\n  return native;\n}>\n\n<div ...nativeAttrs() ...api().getRootProps() data-slot=\"tags-input-root\" class=cn(\"flex flex-col gap-1.5\", input.class)>\n  <if=input.label>\n    <label ...api().getLabelProps() data-slot=\"tags-input-label\" class=\"text-sm font-medium\">${input.label}</label>\n  </if>\n  <div\n    ...api().getControlProps()\n    data-slot=\"tags-input-control\"\n    class=\"border-input flex min-h-9 w-full flex-wrap items-center gap-1.5 rounded-md border bg-transparent px-3 py-1.5 shadow-xs transition-[color,box-shadow] has-[input:focus]:border-ring has-[input:focus]:ring-ring/50 has-[input:focus]:ring-[3px] data-[disabled]:pointer-events-none data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 data-[invalid]:border-destructive data-[invalid]:ring-destructive/20 dark:data-[invalid]:ring-destructive/40\"\n  >\n    <for|value, index| of=api().value>\n      <span\n        ...api().getItemProps({ index, value })\n        data-slot=\"tags-input-item\"\n        class=\"inline-flex items-center rounded-md border border-transparent bg-secondary px-2 py-0.5 text-xs font-medium text-secondary-foreground data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground data-[disabled]:opacity-50\"\n      >\n        <span\n          ...api().getItemPreviewProps({ index, value })\n          data-slot=\"tags-input-item-preview\"\n          class=\"inline-flex items-center gap-1\"\n        >\n          <span ...api().getItemTextProps({ index, value }) data-slot=\"tags-input-item-text\">${value}</span>\n          <button\n            ...api().getItemDeleteTriggerProps({ index, value })\n            data-slot=\"tags-input-item-delete-trigger\"\n            type=\"button\"\n            class=\"inline-flex size-3.5 shrink-0 items-center justify-center rounded-sm outline-none hover:bg-secondary-foreground/20 focus-visible:ring-[3px] focus-visible:ring-ring/50\"\n          >\n            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" class=\"size-3\">\n              <path d=\"M18 6 6 18\"/>\n              <path d=\"m6 6 12 12\"/>\n            </svg>\n            <span class=\"sr-only\">Remove ${value}</span>\n          </button>\n        </span>\n        <input\n          ...api().getItemInputProps({ index, value })\n          data-slot=\"tags-input-item-input\"\n          class=\"w-[--width] min-w-4 bg-transparent text-xs outline-none\"\n        />\n      </span>\n    </for>\n    <input\n      ...api().getInputProps()\n      data-slot=\"tags-input-input\"\n      class=\"h-6 min-w-20 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed\"\n    />\n  </div>\n  <input ...api().getHiddenInputProps()>\n</div>\n\n<return=api>\n"
			}]
		},
