				"target": "~/src/routes/dashboard-01/section-cards.marko",
				"content": "import Badge from \"../../components/ui/badge/badge.marko\";\nimport Card from \"../../components/ui/card/card.marko\";\nimport CardHeader from \"../../components/ui/card/header.marko\";\nimport CardTitle from \"../../components/ui/card/title.marko\";\nimport CardDescription from \"../../components/ui/card/description.marko\";\nimport CardAction from \"../../components/ui/card/action.marko\";\nimport CardFooter from \"../../components/ui/card/footer.marko\";\n\nstatic const METRICS = [\n  {\n    id: \"revenue\",\n    label: \"Total Revenue\",\n    value: \"$1,250.00\",\n    delta: \"+12.5%\",\n    trend: \"up\",\n    headline: \"Trending up this month\",\n    detail: \"Visitors for the last 6 months\",\n  },\n  {\n    id: \"customers\",\n    label: \"New Customers\",\n    value: \"1,234\",\n    delta: \"-20%\",\n    trend: \"down\",\n    headline: \"Down 20% this period\",\n    detail: \"Acquisition needs attention\",\n  },\n  {\n    id: \"accounts\",\n    label: \"Active Accounts\",\n    value: \"45,678\",\n    delta: \"+12.5%\",\n    trend: \"up\",\n    headline: \"Strong user retention\",\n    detail: \"Engagement exceeds targets\",\n  },\n  {\n    id: \"growth\",\n    label: \"Growth Rate\",\n    value: \"4.5%\",\n    delta: \"+4.5%\",\n    trend: \"up\",\n    headline: \"Steady performance increase\",\n    detail: \"Meets growth projections\",\n  },\n];\n\n<div class=\"grid grid-cols-1 gap-4 px-4 sm:grid-cols-2 lg:grid-cols-4 lg:px-6\">\n  <for|metric| of=METRICS by=(metric) => metric.id>\n    <Card class=\"bg-gradient-to-t from-primary/5 to-card shadow-xs\">\n      <CardHeader>\n        <CardDescription>${metric.label}</CardDescription>\n        <CardTitle class=\"text-2xl font-semibold tabular-nums\">${metric.value}</CardTitle>\n        <CardAction>\n          <Badge variant=\"outline\">\n            <if=metric.trend === \"up\">\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                <path d=\"M16 7h6v6\"/>\n                <path d=\"m22 7-8.5 8.5-5-5L2 17\"/>\n              </svg>\n            </if>\n            <else>\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                <path d=\"M16 17h6v-6\"/>\n                <path d=\"m22 17-8.5-8.5-5 5L2 7\"/>\n              </svg>\n            </else>\n            ${metric.delta}\n          </Badge>\n        </CardAction>\n      </CardHeader>\n      <CardFooter class=\"flex-col items-start gap-1.5 text-sm\">\n        <div class=\"line-clamp-1 font-medium\">${metric.headline}</div>\n        <div class=\"text-muted-foreground\">${metric.detail}</div>\n      </CardFooter>\n    </Card>\n  </for>\n</div>\n"
