				"target": "~/src/routes/sidebar-02/app-sidebar.marko",
				"content": "import Sidebar from \"../../components/ui/sidebar/sidebar.marko\";\nimport SidebarHeader from \"../../components/ui/sidebar/header.marko\";\nimport SidebarContent from \"../../components/ui/sidebar/content.marko\";\nimport SidebarGroup from \"../../components/ui/sidebar/group.marko\";\nimport SidebarGroupLabel from \"../../components/ui/sidebar/group-label.marko\";\nimport SidebarMenu from \"../../components/ui/sidebar/menu.marko\";\nimport SidebarMenuItem from \"../../components/ui/sidebar/menu-item.marko\";\nimport SidebarMenuButton from \"../../components/ui/sidebar/menu-button.marko\";\nimport Collapsible from \"../../components/ui/collapsible/collapsible.marko\";\nimport VersionSwitcher from \"./version-switcher.marko\";\nimport SearchForm from \"./search-form.marko\";\n\nexport interface Input {\n  open?: boolean;\n}\n\nstatic const VERSIONS = [\"1.0.1\", \"1.1.0-alpha\", \"2.0.0-beta1\"];\n\nstatic const NAV_MAIN = [\n  {\n    title: \"Getting Started\",\n    url: \"#\",\n    items: [\n      { title: \"Installation\", url: \"#\" },\n      { title: \"Project Structure\", url: \"#\" },\n    ],\n  },\n  {\n    title: \"Build Your Application\",\n    url: \"#\",\n    items: [\n      { title: \"Routing\", url: \"#\" },\n      { title: \"Data Fetching\", url: \"#\", isActive: true },\n      { title: \"Rendering\", url: \"#\" },\n      { title: \"Caching\", url: \"#\" },\n      { title: \"Styling\", url: \"#\" },\n      { title: \"Optimizing\", url: \"#\" },\n      { title: \"Configuring\", url: \"#\" },\n      { title: \"Testing\", url: \"#\" },\n      { title: \"Authentication\", url: \"#\" },\n      { title: \"Deploying\", url: \"#\" },\n      { title: \"Upgrading\", url: \"#\" },\n      { title: \"Examples\", url: \"#\" },\n    ],\n  },\n  {\n    title: \"API Reference\",\n    url: \"#\",\n    items: [\n      { title: \"Components\", url: \"#\" },\n      { title: \"File Conventions\", url: \"#\" },\n      { title: \"Functions\", url: \"#\" },\n      { title: \"next.config.js Options\", url: \"#\" },\n      { title: \"CLI\", url: \"#\" },\n      { title: \"Edge Runtime\", url: \"#\" },\n    ],\n  },\n  {\n    title: \"Architecture\",\n    url: \"#\",\n    items: [\n      { title: \"Accessibility\", url: \"#\" },\n      { title: \"Fast Refresh\", url: \"#\" },\n      { title: \"Next.js Compiler\", url: \"#\" },\n      { title: \"Supported Browsers\", url: \"#\" },\n      { title: \"Turbopack\", url: \"#\" },\n    ],\n  },\n  {\n    title: \"Community\",\n    url: \"#\",\n    items: [{ title: \"Contribution Guide\", url: \"#\" }],\n  },\n];\n\n<Sidebar open=input.open>\n  <@content>\n    <SidebarHeader>\n      <VersionSwitcher versions=VERSIONS defaultVersion=VERSIONS[0]/>\n      <SearchForm/>\n    </SidebarHeader>\n    <SidebarContent class=\"gap-0\">\n      <for|group| of=NAV_MAIN by=(group) => group.title>\n        <Collapsible defaultOpen=true class=\"group/collapsible\">\n          <@trigger|attrs|>\n            <SidebarGroup>\n              <SidebarGroupLabel\n                ...attrs\n                class=\"group/label w-full cursor-pointer text-sm text-sidebar-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground\"\n              >\n                ${group.title}\n                <svg\n                  xmlns=\"http://www.w3.org/2000/svg\"\n                  width=\"24\"\n                  height=\"24\"\n                  viewBox=\"0 0 24 24\"\n                  fill=\"none\"\n                  stroke=\"currentColor\"\n                  stroke-width=\"2\"\n                  stroke-linecap=\"round\"\n                  stroke-linejoin=\"round\"\n                  class=\"ml-auto transition-transform group-data-[state=open]/collapsible:rotate-90\"\n                >\n                  <path d=\"m9 18 6-6-6-6\"/>\n                </svg>\n              </SidebarGroupLabel>\n            </SidebarGroup>\n          </@trigger>\n          <@content>\n            <SidebarGroup class=\"pt-0\">\n              <SidebarMenu>\n                <for|leaf| of=group.items by=(leaf) => leaf.title>\n                  <SidebarMenuItem>\n                    <SidebarMenuButton href=leaf.url active=leaf.isActive>${leaf.title}</SidebarMenuButton>\n                  </SidebarMenuItem>\n                </for>\n              </SidebarMenu>\n            </SidebarGroup>\n          </@content>\n        </Collapsible>\n      </for>\n    </SidebarContent>\n  </@content>\n</Sidebar>\n"
